# Whole-build timeout (owner 2026-10-16): never wait forever on a hung build (e.g. a
# cargo lock deadlock). Default 300 s (a normal rebuild takes about 2 min); 1200 s
# when the build must relift or configure from scratch. TSFP_BUILD_TIMEOUT overrides
# (seconds, 0 disables).
if [ -z "${TSFP_BUILD_TIMEOUT_ACTIVE:-}" ] && command -v timeout >/dev/null 2>&1; then
    build_limit=${TSFP_BUILD_TIMEOUT:-}
    if [ -z "$build_limit" ]; then
        build_limit=300
        case " $* " in *" --relift "*|*" --clean "*|*" --reconfigure "*) build_limit=1200 ;; esac
        [ -f "tmp/${TSFP_BUILD_NAME:-bevy-build-host}/build.ninja" ] || build_limit=1200
        # A stale or missing lift means an automatic relift (several minutes).
        lift_key_now=$(python3 -c 'from tools.private_host import owner_lift_key; print(owner_lift_key())' 2>/dev/null || echo unavailable)
        [ -f "tmp/private-host/lift-$lift_key_now/summary.json" ] || build_limit=1200
    fi
    # Test hook (tests/test_build_timeout.py): print the computed limit and stop.
    [ -z "${TSFP_BUILD_PRINT_LIMIT:-}" ] || { echo "$build_limit"; exit 0; }
    if [ "$build_limit" != 0 ]; then
        TSFP_BUILD_TIMEOUT_ACTIVE=1 timeout --kill-after=30 "$build_limit" sh "$0" "$@"
        rc=$?
        if [ "$rc" = 124 ] || [ "$rc" = 137 ]; then
            echo "build.sh: stopped after ${build_limit}s without finishing; the build was probably hung (for example a cargo lock deadlock). Rerun; if it repeats, send the output to the supervisor. Set TSFP_BUILD_TIMEOUT=<seconds> to change the limit." >&2
        fi
        exit "$rc"
    fi
fi
# Paths are relative to the repository root, resolved from this script's own location. Keep the option list below
# in step with docs/owner-run-guide.md whenever the way the game is built changes.
# CPU diagnostics: tools.t2333_trace retains dummy SDL PCM consumption without a GPU.
#!/bin/sh



set -eu

usage() {
    cat <<'USAGE'
usage: sh tools/dev/build.sh [--clean] [--relift] [--jobs N] [--reconfigure] [--with-tools] [--check-toolchain] [--help]

Configures (if needed) and builds the Bevy-hosted game, then prints the binary, build stamp, git sha and options.
  A stale or missing current lift is relifted automatically (needs retail XBE when uncached).
  --relift       force the private lift pipeline in tmp/private-host (needs retail XBE if uncached)
  --clean        remove the C build dir and the cargo target dir first (full rebuild)
  --jobs N       parallel jobs for ninja and cargo (default: effective CPUs, the cgroup quota in a container)
  --reconfigure  run cmake again even if the build dir exists
  --with-tools   also build tsfp-storage and the off-screen tsfp-ui-preview tools
  --check-toolchain  only verify (and if needed install via rustup) the pinned rustc, then exit
  --help         this text

Environment (all optional):
  TSFP_BUILD_KSERVICES   1 links experimental K-3 Rust/compare selector (default 0; Tier 2 pending)
  TSFP_BUILD_KCLOCK      0 drops the Rust elapsed clock (default 1, Tier 2 EQUAL; runtime TSFP_RUST_KCLOCK=0 selects C)
  TSFP_BUILD_AUDIO_HOST  Rust SoundHost audio host, always on (T3959); =0 is refused
  TSFP_BUILD_INPUT_HLE   1 links the optional Rust XInput enumeration path (default 1; runtime TSFP_RUST_INPUT_HLE=0 selects the C fallback)
  TSFP_BUILD_GAME_BUMP|ARENA|POOL|LEDGER  1 compiles in the default-off Rust game allocator routes (default 0; runtime TSFP_RUST_GAME_* selects)
  TSFP_BUILD_DETSCHED_BACKEDGES  1 enables experimental back-edge handoffs in lifted loops (default 0; T3450)
  TSFP_BUILD_PROFILE     gate applies tools/data/build-profile-gate.env (the modules of the shared gate/adoption prebuilt, T3597)
  TSFP_BUILD_CAPTURE     1 builds the rule-43 capture host (transformed lifted chunks + src/host/t2_capture.c, lifted oracle); never a play host (T3740)
  TSFP_NO_CCACHE         1 disables sccache/ccache, including inherited CMAKE_C_COMPILER_LAUNCHER / RUSTC_WRAPPER
  TSFP_BUILD_NAME        build dir name under tmp/ (default: bevy-build-host if present, else bevy-build)
  TSFP_LIFTED_DIR        directory of the lifted C (default: newest complete current-key lift)
  TSFP_UI_EXTENSIONS    opt-in native UI layers: menu-pointer, mk-settings, back-button (runtime; unset preserves original)
  TSFP_BEVY_CARGO_HOME   offline cargo home with the Bevy crates (default: the unified tmp/rust/cargo, T3472)
Rust fileio support includes disc/FATX, host descriptors/metadata/directory streams, T2225 resolution/create/rename, device mount validation/acquisition/publication and metadata conversion, guest OBJECT_ATTRIBUTES and bounded root-path adapters, and experimental kernel I/O completion (opt-in at play time).
T2309: the configure step also generates the per-page switch of the original page draw (tools/play/ui_draw_hooks.py) from the lift.
The disc image is NOT needed to build. Next step: sh tools/dev/play.sh
USAGE
}

relift=0
clean=0
reconfigure=0
check_toolchain=0
with_tools=0
jobs=""
parse_build_args() {
while [ $# -gt 0 ]; do
    case $1 in
    --help | -h) usage; exit 0 ;;
    --clean) clean=1 ;;
    --relift) relift=1; reconfigure=1 ;;
    --reconfigure) reconfigure=1 ;;
    --with-tools) with_tools=1 ;;
    --check-toolchain) check_toolchain=1 ;;
    --jobs)
        [ $# -ge 2 ] || { echo "build.sh: --jobs needs a number" >&2; exit 2; }
        jobs=$2
        shift
        ;;
    --jobs=*) jobs=${1#--jobs=} ;;
    *) echo "build.sh: unknown argument: $1 (see --help)" >&2; exit 2 ;;
    esac
    shift
done
}
parse_build_args "$@"
case $jobs in
'' | *[!0-9]*) [ -z "$jobs" ] || { echo "build.sh: --jobs must be a positive integer" >&2; exit 2; } ;;
esac
[ "$jobs" != 0 ] || { echo "build.sh: --jobs must be a positive integer" >&2; exit 2; }

root=$(cd "$(dirname "$0")/../.." && pwd)
cd "$root"
# T3745 (docs/t3745-disk-safety.md): temporary files on the data disk, never /tmp on the root
# disk, no core dumps, and the disk budget gate (tools/data/disk_budget.json) before anything is
# written. Exit 3 only on a refusal; a checkout without tools/datadisk.py skips the gate.
# No core dumps (core_pattern pipes them to the host root disk); TSFP_CORE_DUMPS=1 opts in.
[ "${TSFP_CORE_DUMPS:-0}" = 1 ] || ulimit -S -c 0 2>/dev/null || ulimit -c 0
if [ -f "$root/tools/datadisk.py" ] && command -v python3 >/dev/null 2>&1; then
    if tsfp_tmpdir=$(python3 -m tools.datadisk tmpdir 2>/dev/null); then
        export TMPDIR="$tsfp_tmpdir" TMP="$tsfp_tmpdir" TEMP="$tsfp_tmpdir" GIT_CEILING_DIRECTORIES="$tsfp_tmpdir"
    fi
    tsfp_disk_rc=0
    python3 -m tools.datadisk check --kind build --path "$root/tmp" || tsfp_disk_rc=$?
    [ "$tsfp_disk_rc" != 3 ] || exit 3
fi
[ -f tools/build_bevy.sh ] || { echo "build.sh: not a repository root: $root" >&2; exit 2; }
[ -n "$jobs" ] || jobs=$(python3 -m tools.hostcaps cpus 2>/dev/null || nproc 2>/dev/null || echo 4)  # T3844: cgroup CPU quota

# --- toolchain: use the repo-local rust pin only when cargo is not already usable ---
if ! command -v cargo >/dev/null 2>&1 && [ -d tmp/rust/cargo/bin ]; then
    RUSTUP_HOME=$root/tmp/rust/rustup
    CARGO_HOME=$root/tmp/rust/cargo
    PATH=$CARGO_HOME/bin:$PATH
    export RUSTUP_HOME CARGO_HOME PATH
fi
# --- T2151: rustc must be the pin of cmake/rust-ports.cmake (single source of truth, read from there) ---
rust_diag() {
    echo "build.sh: rust toolchain diagnostics (send this if the build fails):" >&2
    echo "  which -a rustc: $(which -a rustc 2>/dev/null | tr '\n' ' ')" >&2
    echo "  rustc --version: $(rustc --version 2>&1)" >&2
    echo "  RUSTUP_TOOLCHAIN='${RUSTUP_TOOLCHAIN:-}' resolved TSFP_RUSTC='${pin_rustc:-}'" >&2
}
pin_rustc=""
if command -v rustc >/dev/null 2>&1 || command -v rustup >/dev/null 2>&1; then
    pin_version=$(sed -n 's/.*STREQUAL "\(rustc [^"]*\)".*/\1/p' cmake/rust-ports.cmake | head -n 1)
    [ -n "$pin_version" ] || { echo "build.sh: cannot read the rustc pin from cmake/rust-ports.cmake" >&2; exit 2; }
    pin_release=$(echo "$pin_version" | cut -d' ' -f2)
    # Prefer the pinned toolchain's own rustc (beats an older /usr/bin/rustc ahead of the rustup shim and per-directory overrides).
    use_pinned_toolchain() {
        candidate=$(rustup which rustc --toolchain "$pin_release" 2>/dev/null) || return 1
        [ "$("$candidate" --version 2>/dev/null)" = "$pin_version" ] || return 1
        RUSTUP_TOOLCHAIN=$pin_release
        PATH=$(dirname "$candidate"):$PATH
        export RUSTUP_TOOLCHAIN PATH
        pin_rustc=$candidate
        echo "build.sh: using pinned toolchain $pin_release ($pin_rustc, RUSTUP_TOOLCHAIN=$pin_release) for rustc and cargo"
    }
    if command -v rustup >/dev/null 2>&1 && use_pinned_toolchain; then
        :
    elif [ "$(rustc --version 2>/dev/null)" = "$pin_version" ]; then
        pin_rustc=$(command -v rustc)
    else
        echo "build.sh: rustc is '$(rustc --version 2>/dev/null)', the build needs '$pin_version'"
        if command -v rustup >/dev/null 2>&1; then
            echo "build.sh: running: rustup toolchain install $pin_release --profile minimal"
            rustup toolchain install "$pin_release" --profile minimal
            use_pinned_toolchain || { echo "build.sh: rustup did not provide $pin_version after the install" >&2; rust_diag; exit 7; }
        else
            echo "build.sh: rustup not found. Install it and the pinned toolchain, then run this again:" >&2
            echo "  Arch: sudo pacman -S rustup" >&2
            echo "        rustup toolchain install $pin_release --profile minimal" >&2
            rust_diag
            exit 7
        fi
    fi
    echo "build.sh: rustc OK ($pin_version)"
    [ "$check_toolchain" = 0 ] || exit 0
fi
missing=""
required="cmake ninja clang cargo rustc"
[ -n "${TSFP_SOURCE_COMMIT:-}" ] || required="$required git"  # T3760: exec trees carry their identity
for tool in $required; do
    command -v "$tool" >/dev/null 2>&1 || missing="$missing $tool"
done
if [ -n "$missing" ]; then
    echo "build.sh: missing tools:$missing" >&2
    echo "  Arch: sudo pacman -S cmake ninja clang git rustup && rustup default stable" >&2
    echo "  Faster rebuilds (optional): sudo pacman -S sccache lld   (see docs/t-build-speed.md, T2454)" >&2
    exit 3
fi

# T2454: optional speed tools. lld is used only when clang can really link with it.
use_lld=0
if command -v ld.lld >/dev/null 2>&1 && printf 'int main(void){return 0;}\n' | clang -fuse-ld=lld -x c - -o /dev/null >/dev/null 2>&1; then
    use_lld=1
fi
# Compiler cache: sccache (else ccache) for C and, through RUSTC_WRAPPER, for cargo crates.
# sccache cannot cache incremental crates, so only the registry dependencies (profile
# package."*", incremental = false) are cached; local crates keep rustc incremental.
# Explicit wrappers are respected normally. TSFP_NO_CCACHE=1 is a complete opt-out,
# including wrappers inherited from tools.wt or a previously configured build.
if [ "${TSFP_NO_CCACHE:-0}" = 1 ]; then
    unset CMAKE_C_COMPILER_LAUNCHER RUSTC_WRAPPER
fi
cc_launcher=""
if [ "${TSFP_NO_CCACHE:-0}" != 1 ]; then
    if command -v sccache >/dev/null 2>&1; then
        # I-claude1-sccache: never a bare sccache for C, it aborts under CARGO_INCREMENTAL=1
        cc_launcher=sccache
        [ -f "$root/tools/wt/sccache-cc.sh" ] && cc_launcher=$root/tools/wt/sccache-cc.sh
    elif command -v ccache >/dev/null 2>&1; then cc_launcher=ccache
    fi
    if [ -n "$cc_launcher" ]; then
        if [ -z "${RUSTC_WRAPPER:-}" ] && [ "$cc_launcher" = sccache ]; then
            RUSTC_WRAPPER=sccache
            export RUSTC_WRAPPER
        fi
        echo "build.sh: compiler cache: $cc_launcher (TSFP_NO_CCACHE=1 disables)"
    fi
fi

name=${TSFP_BUILD_NAME:-}
if [ -z "$name" ]; then
    if [ -d tmp/bevy-build-host ]; then name=bevy-build-host; else name=bevy-build; fi
fi
dir=tmp/$name
target_dir=${CARGO_TARGET_DIR:-$root/tmp/bevy-target}
case $target_dir in /*) ;; *) target_dir=$root/$target_dir ;; esac
export CARGO_TARGET_DIR=$target_dir
CARGO_BUILD_JOBS=$jobs
export CARGO_BUILD_JOBS

# Local owner builds keep the tsfp-ports rustc frontend bounded. Remote build
# workers retain the faster eight-thread setting; explicit overrides still win.
if [ "${TSFP_BUILD_REMOTE+x}" != x ] && [ -z "${TSFP_RUST_PORTS_THREADS:-}" ]; then
    export TSFP_BUILD_LOCAL=1
fi

# T2233: the owner runs tools/dev/play.sh from the same checkout tree, so an agent build into the shared default directories rewrites the
# libraries and binary under a running or starting game ("cannot open shared object file", exit 127). Agents build elsewhere.
case "$name:$target_dir" in
bevy-build-host:* | bevy-build:* | *:"$root"/tmp/bevy-target) shared_default=1 ;;
*) shared_default=0 ;;
esac
if [ "$shared_default" = 1 ] && [ "${TSFP_OWNER_BUILD:-0}" != 1 ] && { [ "${TSFP_AGENT:-0}" = 1 ] || [ -n "${CLAUDECODE:-}" ] || [ -n "${CODEX_SANDBOX:-}" ]; }; then
    echo "build.sh: refusing to build into the owner's shared directories (tmp/$name, $target_dir) from an agent session." >&2
    echo "  Build in your own CMake dir and keep the SHARED cargo target (T2439, do not set CARGO_TARGET_DIR to a private path):" >&2
    echo "    TSFP_BUILD_NAME=<task>-build CARGO_TARGET_DIR=<main>/tmp/wt-cache/cargo-target/default sh tools/dev/build.sh   (python3 -m tools.wt run does this)" >&2
    echo "  The owner's own build sets TSFP_OWNER_BUILD=1 to skip this check." >&2
    exit 9
fi

# Refuse unsafe destinations before admission can wait on or synchronize a shared tree.
# The public build.sh entry may be invoked without `tools.wt run`. Re-enter
# through the shared wrapper once, which takes the host build slot and canonical
# target lock before this script continues.
if [ "${TSFP_BUILD_SLOT_HELD+x}" != x ] && [ "${TSFP_BUILD_ADMISSION:-on}" != off ]; then
    export TSFP_BUILD_SLOT_HELD=1
    exec python3 -m tools.wt run --family default -- sh tools/dev/build.sh "$@"
fi

# --- options of the configure step (single list, printed at the end) ---
# T1990: mutation hooks are opt-in. Bevy's Rust ports rlib also needs the cfg in RUSTFLAGS.
opts="-DCMAKE_C_COMPILER=clang -DCMAKE_BUILD_TYPE=Release -DTSFP_LIFTED_OPT=-O2 -DTSFP_RUST_PORTS=ON -DTSFP_RUST_MAIN=ON -DTSFP_RUST_BEVY=ON -DTSFP_RUST_FILEIO=ON -DTSFP_RUST_KMEM=ON -DTSFP_RUST_RT_HOST=ON"
# T3740: TSFP_BUILD_CAPTURE=1 builds the capture host of rule 43 (docs/t3738-capture-design.md): transformed lifted chunks
# plus src/host/t2_capture.c. It also defaults TSFP_LIFTED_ORACLE to 1 so the lifted original answers everywhere. Never a
# play or gate host: use its own TSFP_BUILD_NAME. Recording needs TSFP_T2_CAPTURE=<spool> at run time.
case "${TSFP_BUILD_CAPTURE:-}" in  # not a profile switch (a measurement build, T3740)
    "" | 0) capture_option=OFF ;;
    1) capture_option=ON; TSFP_LIFTED_ORACLE=${TSFP_LIFTED_ORACLE:-1} ;;
    *) echo "build.sh: TSFP_BUILD_CAPTURE must be 0 or 1" >&2; exit 2 ;;
esac
# T3833: TSFP_CAPTURE_KIND=play is the live targeted capture host of play.sh --capture-targets: a capture build that keeps
# the normal Rust defaults (no lifted-oracle switches), keyed apart from the oracle capture host (tools.wt prebuilt).
case "${TSFP_CAPTURE_KIND:-}" in
    "" | oracle) ;;
    play) [ "$capture_option" = ON ] || { echo "build.sh: TSFP_CAPTURE_KIND=play needs TSFP_BUILD_CAPTURE=1" >&2; exit 2; }
        TSFP_LIFTED_ORACLE=0 ;;
    *) echo "build.sh: TSFP_CAPTURE_KIND must be oracle or play" >&2; exit 2 ;;
esac
opts="$opts -DTSFP_BUILD_CAPTURE=$capture_option"
# T3935: the host-memory capture driver recorded the retired C guest memory; there is no capture build any more.
case "${TSFP_HOSTMEM_CAPTURE_PRODUCTION:-}" in
    "" | 0) ;;
    *) echo "build.sh: TSFP_HOSTMEM_CAPTURE_PRODUCTION is retired with the C kernel memory (T3935)" >&2; exit 2 ;;
esac
# T3824: TSFP_BUILD_LIVE_CENSUS=1 builds the live hit census (src/host/live_census.c, -finstrument-functions on the lifted
# chunks): play.sh then writes tmp/play/<run>/census-hits.bin and keeps a copy in tmp/live-census. Unset takes the
# default of tools/data/live_census.json (ON only when the measured overhead is under its threshold). Off with capture.
live_census_build=${TSFP_BUILD_LIVE_CENSUS:-}
if [ -z "$live_census_build" ]; then
    if [ "$capture_option" = ON ]; then live_census_build=0
    elif [ "$(python3 -m tools.live_census gate 2>/dev/null)" = ON ]; then live_census_build=1
    else live_census_build=0; fi
fi
case $live_census_build in
    0) live_census_option=OFF ;;
    1) live_census_option=ON ;;
    *) echo "build.sh: TSFP_BUILD_LIVE_CENSUS must be 0 or 1" >&2; exit 2 ;;
esac
opts="$opts -DTSFP_LIVE_CENSUS=$live_census_option"
echo "build.sh: live hit census $live_census_option ($(python3 -m tools.live_census gate --explain 2>/dev/null || echo 'gate unreadable'))"
# Separate from the host cargo target: the host build script runs ninja while the
# outer cargo holds the target-dir lock, so a shared dir deadlocks (2026-10-16).
rt_host_target_dir=$target_dir-rt-host
opts="$opts -DTSFP_RT_HOST_TARGET_DIR=$rt_host_target_dir"
# T3597: TSFP_BUILD_PROFILE=<name> applies tools/data/build-profile-<name>.env (TSFP_BUILD_*=1 lines) as defaults,
# an explicit TSFP_BUILD_* in the environment wins. The shared gate/adoption prebuilt uses profile "gate"
# (tools/wt/prebuilt.py exports the same list), so `TSFP_BUILD_PROFILE=gate sh tools/dev/build.sh` builds the gate host's modules.
if [ -n "${TSFP_BUILD_PROFILE:-}" ]; then
    case $TSFP_BUILD_PROFILE in *[!a-z0-9-]*) echo "build.sh: invalid TSFP_BUILD_PROFILE" >&2; exit 2 ;; esac
    profile_file=$root/tools/data/build-profile-$TSFP_BUILD_PROFILE.env
    [ -f "$profile_file" ] || { echo "build.sh: unknown TSFP_BUILD_PROFILE=$TSFP_BUILD_PROFILE (no $profile_file)" >&2; exit 2; }
    while IFS='=' read -r profile_key profile_value; do
        case $profile_key in
            ''|'#'*) continue ;;
            TSFP_BUILD_*) ;;
            *) echo "build.sh: bad line in $profile_file: $profile_key" >&2; exit 2 ;;
        esac
        case $profile_key in *[!A-Z0-9_]*) echo "build.sh: bad switch $profile_key in $profile_file" >&2; exit 2 ;; esac
        eval "profile_current=\${$profile_key:-}"
        if [ -z "$profile_current" ]; then
            eval "$profile_key=\$profile_value"
            eval "export $profile_key"
        fi
    done < "$profile_file"
    echo "build.sh: build profile $TSFP_BUILD_PROFILE ($profile_file)"
fi
case ${TSFP_BUILD_GAME_BUMP:-1} in
    0) game_bump_option=OFF ;;
    1) game_bump_option=ON ;;
    *) echo "build.sh: TSFP_BUILD_GAME_BUMP must be 0 or 1" >&2; exit 2 ;;
esac
opts="$opts -DTSFP_RUST_GAME_BUMP=$game_bump_option"
case ${TSFP_BUILD_GAME_ARENA:-0} in
    0) game_arena_option=OFF ;;
    1) game_arena_option=ON ;;
    *) echo "build.sh: TSFP_BUILD_GAME_ARENA must be 0 or 1" >&2; exit 2 ;;
esac
opts="$opts -DTSFP_RUST_GAME_ARENA=$game_arena_option"
case ${TSFP_LIFTED_ORACLE:-0} in
    0) lifted_oracle_option=OFF ;;
    1) lifted_oracle_option=ON ;;
    *) echo "build.sh: TSFP_LIFTED_ORACLE must be 0 or 1" >&2; exit 2 ;;
esac
opts="$opts -DTSFP_LIFTED_ORACLE=$lifted_oracle_option"
case ${TSFP_BUILD_GAME_POOL:-0} in
    0) game_pool_option=OFF ;;
    1) game_pool_option=ON ;;
    *) echo "build.sh: TSFP_BUILD_GAME_POOL must be 0 or 1" >&2; exit 2 ;;
esac
opts="$opts -DTSFP_RUST_GAME_POOL=$game_pool_option"
case ${TSFP_BUILD_GAME_LEDGER:-0} in
    0) game_ledger_option=OFF ;;
    1) game_ledger_option=ON ;;
    *) echo "build.sh: TSFP_BUILD_GAME_LEDGER must be 0 or 1" >&2; exit 2 ;;
esac
opts="$opts -DTSFP_RUST_GAME_LEDGER=$game_ledger_option"
# T3959: the Rust audio host is the only audio build (the C host units are retired); =0 is refused.
if [ -z "${TSFP_BUILD_AUDIO_HOST:-}" ] && [ -n "${TSFP_RUST_AUDIO_HOST:-}" ]; then TSFP_BUILD_AUDIO_HOST=$TSFP_RUST_AUDIO_HOST; fi
case ${TSFP_BUILD_AUDIO_HOST:-1} in
    0) echo "build.sh: TSFP_BUILD_AUDIO_HOST=0 / TSFP_RUST_AUDIO_HOST=0 is retired (T3959): the C audio host was removed" >&2; exit 2 ;;
    1) audio_host_option=ON ;;
    *) echo "build.sh: TSFP_BUILD_AUDIO_HOST (or TSFP_RUST_AUDIO_HOST) must be 1" >&2; exit 2 ;;
esac
opts="$opts -DTSFP_RUST_AUDIO_HOST=$audio_host_option"
case ${TSFP_BUILD_WSOLA:-1} in
    0) echo "build.sh: TSFP_BUILD_WSOLA=0 is retired (T3879): the C WSOLA engine is oracle only" >&2; exit 2 ;;
    1) wsola_option=ON ;;
    *) echo "build.sh: TSFP_BUILD_WSOLA must be 0 or 1" >&2; exit 2 ;;
esac
opts="$opts -DTSFP_RUST_WSOLA=$wsola_option"
case ${TSFP_BUILD_INPUT_HLE:-1} in
    0) input_hle_option=OFF ;;
    1) input_hle_option=ON ;;
    *) echo "build.sh: TSFP_BUILD_INPUT_HLE must be 0 or 1" >&2; exit 2 ;;
esac
opts="$opts -DTSFP_RUST_INPUT_HLE=$input_hle_option"
if [ "$use_lld" = 1 ]; then
    # Keep the C and Rust host links on the same fast linker when it is installed.
    opts="$opts -DCMAKE_EXE_LINKER_FLAGS=-fuse-ld=lld -DCMAKE_SHARED_LINKER_FLAGS=-fuse-ld=lld"
fi
if [ -n "$cc_launcher" ] && [ -z "${CMAKE_C_COMPILER_LAUNCHER:-}" ]; then
    opts="$opts -DCMAKE_C_COMPILER_LAUNCHER=$cc_launcher"
    # an existing build dir configured without a launcher gets it once (one full C rebuild, then cached)
    if [ -f "$dir/CMakeCache.txt" ] && ! grep -q '^CMAKE_C_COMPILER_LAUNCHER:[A-Z]*=.' "$dir/CMakeCache.txt"; then
        reconfigure=1
    fi
fi
# A cache configured with a bare `sccache` launcher (older build.sh) fails every C file once
# CARGO_INCREMENTAL=1 reaches ninja (CMake keeps the cached value over the environment): rewrite it.
if [ "${TSFP_NO_CCACHE:-0}" != 1 ] && [ -f "$dir/CMakeCache.txt" ] &&
    grep -q '^CMAKE_C_COMPILER_LAUNCHER:[A-Z]*=sccache$' "$dir/CMakeCache.txt"; then
    safe_launcher=${CMAKE_C_COMPILER_LAUNCHER:-}
    [ -z "$safe_launcher" ] || [ "$safe_launcher" = sccache ] && safe_launcher=$cc_launcher
    if [ -n "$safe_launcher" ] && [ "$safe_launcher" != sccache ]; then
        opts="$opts -DCMAKE_C_COMPILER_LAUNCHER=$safe_launcher"
        reconfigure=1
    fi
fi
if [ "${TSFP_NO_CCACHE:-0}" = 1 ] && [ -f "$dir/CMakeCache.txt" ] && grep -q '^CMAKE_C_COMPILER_LAUNCHER:[A-Z]*=.' "$dir/CMakeCache.txt"; then
    # CMake preserves this cached setting unless it is explicitly reset. Reset it
    # in the configure options so an existing cache cannot defeat the opt-out.
    opts="$opts -DCMAKE_C_COMPILER_LAUNCHER="
    reconfigure=1
fi

case ${TSFP_RUST_LANE_MUTATION:-OFF} in
    OFF|0) lane_mutation_option=OFF ;;
    ON|1) lane_mutation_option=ON ;;
    *) echo "build.sh: TSFP_RUST_LANE_MUTATION must be ON or OFF" >&2; exit 2 ;;
esac
opts="$opts -DTSFP_RUST_LANE_MUTATION=$lane_mutation_option"

case ${TSFP_BUILD_KCLOCK:-1} in
    0) kclock_option=OFF ;;
    1) kclock_option=ON ;;
    *) echo "build.sh: TSFP_BUILD_KCLOCK must be 0 or 1" >&2; exit 2 ;;
esac
opts="$opts -DTSFP_RUST_KCLOCK=$kclock_option"
case ${TSFP_BUILD_KSERVICES:-0} in
    0) kservices_option=OFF ;;
    1) kservices_option=ON ;;
    *) echo "build.sh: TSFP_BUILD_KSERVICES must be 0 or 1" >&2; exit 2 ;;
esac
opts="$opts -DTSFP_RUST_KSERVICES=$kservices_option"
case ${TSFP_BUILD_NATIVE_FILEIO:-1} in
    0) echo "build.sh: TSFP_BUILD_NATIVE_FILEIO=0 is retired: kernel_file.c and xdvdfs.c were removed (T3931)" >&2; exit 2 ;;
    1) native_fileio_option=ON ;;
    *) echo "build.sh: TSFP_BUILD_NATIVE_FILEIO must be 0 or 1" >&2; exit 2 ;;
esac
opts="$opts -DTSFP_NATIVE_FILEIO=$native_fileio_option"
case ${TSFP_BUILD_DETSCHED_BACKEDGES:-0} in
    0) detsched_backedges_option=OFF ;;
    1) detsched_backedges_option=ON ;;
    *) echo "build.sh: TSFP_BUILD_DETSCHED_BACKEDGES must be 0 or 1" >&2; exit 2 ;;
esac
opts="$opts -DTSFP_DETSCHED_BACKEDGES=$detsched_backedges_option"
if [ -f "$dir/CMakeCache.txt" ] && ! grep -qx "TSFP_RUST_KSERVICES:BOOL=$kservices_option" "$dir/CMakeCache.txt"; then
    reconfigure=1
fi
if [ -f "$dir/CMakeCache.txt" ] && ! grep -qx "TSFP_DETSCHED_BACKEDGES:BOOL=$detsched_backedges_option" "$dir/CMakeCache.txt"; then
    reconfigure=1
fi
# T3597: the game allocator modules are configure-time options too; a build dir configured without them must be reconfigured.
for game_cmake_pair in "BUMP:$game_bump_option" "ARENA:$game_arena_option" "POOL:$game_pool_option" "LEDGER:$game_ledger_option"; do
    if [ -f "$dir/CMakeCache.txt" ] && ! grep -qx "TSFP_RUST_GAME_${game_cmake_pair%%:*}:BOOL=${game_cmake_pair#*:}" "$dir/CMakeCache.txt"; then
        reconfigure=1
    fi
done
if [ -f "$dir/CMakeCache.txt" ] && ! grep -qx "TSFP_BUILD_CAPTURE:BOOL=$capture_option" "$dir/CMakeCache.txt"; then
    reconfigure=1
fi
if [ -f "$dir/CMakeCache.txt" ] && ! grep -qx "TSFP_LIVE_CENSUS:BOOL=$live_census_option" "$dir/CMakeCache.txt"; then
    reconfigure=1
fi
if [ -f "$dir/CMakeCache.txt" ] && ! grep -qx "TSFP_LIFTED_ORACLE:BOOL=$lifted_oracle_option" "$dir/CMakeCache.txt"; then
    reconfigure=1
fi
if [ -f "$dir/CMakeCache.txt" ] && ! grep -qx "TSFP_RUST_KCLOCK:BOOL=$kclock_option" "$dir/CMakeCache.txt"; then
    reconfigure=1
fi
if [ -f "$dir/CMakeCache.txt" ] && ! grep -qx "TSFP_RUST_AUDIO_HOST:BOOL=$audio_host_option" "$dir/CMakeCache.txt"; then
    reconfigure=1
fi
if [ -f "$dir/CMakeCache.txt" ] && ! grep -qx "TSFP_RUST_WSOLA:BOOL=$wsola_option" "$dir/CMakeCache.txt"; then
    reconfigure=1
fi
if [ -f "$dir/CMakeCache.txt" ] && ! grep -qx "TSFP_RUST_INPUT_HLE:BOOL=$input_hle_option" "$dir/CMakeCache.txt"; then
    reconfigure=1
fi
if [ -f "$dir/CMakeCache.txt" ] && ! grep -qx "TSFP_RT_HOST_TARGET_DIR:[A-Z]*=$rt_host_target_dir" "$dir/CMakeCache.txt"; then
    reconfigure=1
fi
# These host modules are always enabled. Reconfigure a build directory that came
# from a profile or checkout that left any of them disabled.
for required_rust_module in TSFP_RUST_PORTS TSFP_RUST_MAIN TSFP_RUST_BEVY TSFP_RUST_FILEIO TSFP_RUST_KMEM TSFP_RUST_RT_HOST; do
    if [ -f "$dir/CMakeCache.txt" ] && ! grep -qx "$required_rust_module:BOOL=ON" "$dir/CMakeCache.txt"; then
        reconfigure=1
    fi
done
if [ "$use_lld" = 1 ] && [ -f "$dir/CMakeCache.txt" ] \
    && { ! grep -qx 'CMAKE_EXE_LINKER_FLAGS:STRING=-fuse-ld=lld' "$dir/CMakeCache.txt" \
        || ! grep -qx 'CMAKE_SHARED_LINKER_FLAGS:STRING=-fuse-ld=lld' "$dir/CMakeCache.txt"; }; then
    reconfigure=1
fi
# a cached TSFP_RUSTC from an earlier configure would keep the old compiler: reconfigure when it differs
if [ -n "$pin_rustc" ] && [ -f "$dir/CMakeCache.txt" ] && ! grep -qx "TSFP_RUSTC:[A-Z]*=$pin_rustc" "$dir/CMakeCache.txt"; then
    echo "build.sh: cached TSFP_RUSTC in $dir differs from $pin_rustc, reconfiguring"
    reconfigure=1
fi
# T2165: pick the lifted C by CONTENT, never by glob order (the glob took the alphabetically last key, an old
# pre-patch-35 lift that still had RECOMP_FLAGS_UNRESOLVED at 0x48E61). Order: TSFP_LIFTED_DIR, the lift named by
# tmp/private-host/current.json (the last tools.private_host build), else the newest COMPLETE lift (summary/summary.json
# plus KEY.txt; staged lift-*.tmp-* directories are never selectable).
complete_lift_dir() {
    case $1 in
        */lift-*.tmp-*/gen) return 1 ;;
    esac
    lift_parent=${1%/gen}
    case ${lift_parent##*/} in
        lift-*) ;;
        *) return 1 ;;
    esac
    [ -f "$lift_parent/summary/summary.json" ] && [ -f "$lift_parent/KEY.txt" ]
}
lifted=${TSFP_LIFTED_DIR:-}
if [ -n "$lifted" ] && ! complete_lift_dir "$lifted"; then
    echo "build.sh: selected lifted C directory is incomplete: $lifted" >&2
    exit 4
fi
if [ -z "$lifted" ] && [ -f tmp/private-host/current.json ]; then
    cur_key=$(sed -n 's/.*"key": *"\([0-9a-f]*\)".*/\1/p' tmp/private-host/current.json | head -n 1)
    [ -z "$cur_key" ] || ! complete_lift_dir "tmp/private-host/lift-$cur_key/gen" || lifted=$root/tmp/private-host/lift-$cur_key/gen
fi
if [ -z "$lifted" ]; then
    for candidate in $(ls -dt tmp/private-host/lift-*/gen 2>/dev/null); do
        if complete_lift_dir "$candidate"; then lifted=$root/$candidate; break; fi
    done
fi
# Validate the selected lift before cleaning, configuring or compiling.
if [ -z "$lifted" ] && [ -f "$dir/CMakeCache.txt" ]; then
    cached_lifted=$(sed -n 's/^TSFP_LIFTED_DIR:[A-Z]*=//p' "$dir/CMakeCache.txt")
    if [ -n "$cached_lifted" ] && complete_lift_dir "$cached_lifted"; then lifted=$cached_lifted; fi
fi
selected_lifted=$lifted
if [ "$relift" = 1 ]; then
    # The publisher reuses a complete matching lift, even though this option forces
    # the lift pipeline to run.
    python3 -m tools.private_host --force-lift --lift-only build
fi
current_key=$(python3 -c 'import sys; from pathlib import Path; from tools.private_host import owner_lift_key; p=Path(sys.argv[1]) if sys.argv[1] else None; print(owner_lift_key(p))' "$selected_lifted")
current_lift=$root/tmp/private-host/lift-$current_key/gen
if [ "$current_key" != unavailable ] && complete_lift_dir "$current_lift"; then
    # Prefer an already published current-key lift over an old current.json pointer,
    # an explicit stale selection, or a lift recorded by an old CMake cache.
    selected_lifted=$current_lift
elif [ "$relift" = 0 ]; then
    if [ -n "$selected_lifted" ] && [ -d "$selected_lifted" ]; then
        lift_key=$(basename "$(dirname "$selected_lifted")")
        lift_key=${lift_key#lift-}
        reason="lift is stale (key $lift_key; current key $current_key)"
    else
        reason="no complete lift for current key $current_key"
    fi
    echo "build.sh: $reason; relifting automatically"
    python3 -m tools.private_host --force-lift --lift-only build
    current_key=$(python3 -c 'from tools.private_host import owner_lift_key; print(owner_lift_key())')
    current_lift=$root/tmp/private-host/lift-$current_key/gen
    if [ "$current_key" = unavailable ] || ! complete_lift_dir "$current_lift"; then
        echo "build.sh: relift did not publish a complete lift for key $current_key" >&2
        exit 4
    fi
    selected_lifted=$current_lift
fi
if [ -z "$selected_lifted" ] || [ ! -d "$selected_lifted" ]; then
    echo "build.sh: no complete lifted C directory after relift" >&2
    exit 4
fi
lift_key=$(basename "$(dirname "$selected_lifted")")
lift_key=${lift_key#lift-}
if [ "$current_key" = unavailable ] || [ "$lift_key" != "$current_key" ]; then
    echo "build.sh: relift selected key $lift_key but current key is $current_key" >&2
    exit 10
fi
lifted=$selected_lifted
if [ "$clean" = 1 ]; then
    echo "build.sh: --clean: removing $dir and $target_dir"
    rm -rf "$dir" "$target_dir"
fi

if [ -n "$lifted" ] && [ -f "$dir/CMakeCache.txt" ] && ! grep -qx "TSFP_LIFTED_DIR:[A-Z]*=$lifted" "$dir/CMakeCache.txt"; then
    echo "build.sh: cached TSFP_LIFTED_DIR in $dir differs from $lifted, reconfiguring"
    reconfigure=1
fi
if [ -f "$dir/CMakeCache.txt" ]; then
    cached_lifted=$(sed -n 's/^TSFP_LIFTED_DIR:[A-Z]*=//p' "$dir/CMakeCache.txt")
    if [ -z "$cached_lifted" ] || [ ! -f "$cached_lifted/recomp_dispatch.c" ]; then
        echo "build.sh: cached CMake directory has no lifted code, reconfiguring"
        reconfigure=1
    fi
fi
# I-T3847-1: a build dir configured from another checkout path (an agent container's mount vs the
# owner's host path) makes CMake refuse the cache; drop the cache files, never the build outputs.
if [ -f "$dir/CMakeCache.txt" ]; then
    cached_home=$(sed -n 's/^CMAKE_HOME_DIRECTORY:[A-Z]*=//p' "$dir/CMakeCache.txt")
    if [ -n "$cached_home" ] && [ "$cached_home" != "$root" ]; then
        echo "build.sh: $dir was configured from $cached_home, not $root: dropping its CMake cache"
        rm -f "$dir/CMakeCache.txt"
        rm -rf "$dir/CMakeFiles"
        reconfigure=1
    fi
fi
build_stage() { shift; "$@"; }
if [ -n "${TSFP_BUILD_STAGE_RECEIPT:-}" ]; then
    . tools/dev/build_stage.sh
fi
if [ ! -f "$dir/build.ninja" ] || [ "$reconfigure" = 1 ]; then
    if [ -z "$lifted" ] || [ ! -d "$lifted" ]; then
        echo "build.sh: no complete lifted C directory (tmp/private-host/lift-*/gen). Set TSFP_LIFTED_DIR, see docs/owner-run-guide.md" >&2
        exit 4
    fi
    echo "build.sh: configuring $dir (lifted dir: $lifted)"
    rustc_opt=""
    [ -z "$pin_rustc" ] || rustc_opt="-DTSFP_RUSTC=$pin_rustc"
    # shellcheck disable=SC2086
    build_stage configure cmake -S . -B "$dir" -G Ninja -UTSFP_RUSTC $opts $rustc_opt "-DTSFP_LIFTED_DIR=$selected_lifted" || { rust_diag; exit 8; }
else
    echo "build.sh: $dir already configured (use --reconfigure to run cmake again)"
fi

# T2424/T3472: the prebuilt/gate caller passes the same Bevy home resolved by tools.wt.
# Honor it first: linked worktree and sparse-clone git-common-dir layouts do not imply that
# the main checkout is the parent directory of the common git dir.
if [ -n "${TSFP_BEVY_CARGO_HOME:-}" ]; then
    cargo_home=$TSFP_BEVY_CARGO_HOME
else
    common_dir=$(git -C "$root" rev-parse --path-format=absolute --git-common-dir 2>/dev/null || true)
    case $common_dir in
        /*) main_root=$(dirname "$common_dir") ;;
        *) main_root=$root ;;
    esac
    # T3472: one cargo home; prefer it once legacy Bevy crates have been merged.
    if [ -f "$main_root/tmp/rust/cargo/registry/.tsfp-t3472-merged.json" ]; then
        cargo_home=$main_root/tmp/rust/cargo
    else
        cargo_home=$main_root/tmp/spikes-cargo-home
        [ -d "$cargo_home/registry" ] || cargo_home=$main_root/tmp/rust/cargo
    fi
fi
if [ ! -d "$cargo_home/registry" ]; then
    echo "build.sh: no offline cargo home with the Bevy crates at $cargo_home (set TSFP_BEVY_CARGO_HOME), see docs/t-bevy-spike.md" >&2
    exit 5
fi
TSFP_BEVY_CARGO_HOME=$cargo_home
export TSFP_BEVY_CARGO_HOME
if [ "$use_lld" = 1 ]; then
    CARGO_TARGET_X86_64_UNKNOWN_LINUX_GNU_LINKER=clang
    export CARGO_TARGET_X86_64_UNKNOWN_LINUX_GNU_LINKER
    case " ${RUSTFLAGS:-} " in
        *" -C link-arg=-fuse-ld=lld "*) ;;
        *) RUSTFLAGS="${RUSTFLAGS:+$RUSTFLAGS }-C link-arg=-fuse-ld=lld"; export RUSTFLAGS ;;
    esac
fi

# tools/build_bevy.sh runs ninja without -j, so build the C side here with -j first (the second ninja run is then a no-op)
echo "build.sh: building with $jobs jobs"
# T3806: tools/dev/ninja_host.sh retries once after clearing stale rustc incremental state (undefined .llvm. symbols)
# T3879: the native no-C fileio host links tsfp_host_bevylink like every other host, so gates and regress can run it.
build_stage host sh tools/dev/ninja_host.sh "$dir" "$jobs" tsfp_host_bevylink
sh tools/build_bevy.sh "$name"

# T2396: opt-in diagnostic tools share the host target/profile so their compatible
# workspace artifacts can be reused. Neither tool is needed to build or play the game.
ui_preview=$target_dir/release/tsfp-ui-preview
storage_tool=$target_dir/release/tsfp-storage
if [ "$with_tools" = 1 ]; then
    CARGO_HOME=$cargo_home cargo build --locked --offline --release -j "$jobs" \
        -p tsfp-engine-fileio --bin tsfp-storage
    # T2307: fetch open outline fonts when available; the preview also builds without them.
    sh tools/dev/fetch_fonts.sh || echo "build.sh: open UI fonts not fetched (TSFP_UI_FONTS=outline then needs your own fonts in TSFP_UI_FONT_DIR)" >&2
    if (cd crates/tsfp-ui-wgpu && CARGO_HOME=$cargo_home CARGO_TARGET_DIR=$target_dir cargo build --offline --release -j "$jobs" --features outline-fonts --bin tsfp-ui-preview); then
        ui_preview_state="built (outline fonts: TSFP_UI_FONTS=outline)"
    elif (cd crates/tsfp-ui-wgpu && CARGO_HOME=$cargo_home CARGO_TARGET_DIR=$target_dir cargo build --offline --release -j "$jobs" --bin tsfp-ui-preview); then
        ui_preview_state="built (without outline fonts: ab_glyph not in the cargo home)"
    else
        ui_preview_state="FAILED (play.sh ui-rust unavailable, the game build is unaffected)"
    fi
else
    ui_preview_state="skipped (pass --with-tools for ui-rust and storage-import)"
fi

bin=$target_dir/release/tsfp-bevy
# T2150: record what was built, play.sh compares this with the checkout before running.
stamp_file=${TSFP_BUILD_STAMP:-$target_dir/release/.tsfp-build-stamp}
TSFP_STAMP_LIFT_KEY=$lift_key sh tools/dev/stamp.sh > "$stamp_file"
# Owner report 2026-10-24: tell play.sh which binary this run built (CARGO_TARGET_DIR may not be the default).
last_build=${TSFP_LAST_BUILD:-$root/tmp/play/last-build.json}
mkdir -p "$(dirname "$last_build")"
printf '{\n  "path": "%s",\n  "git_sha": "%s",\n  "stamp_file": "%s"\n}\n' "$bin" "${TSFP_SOURCE_COMMIT:-$(git rev-parse HEAD 2>/dev/null || echo unknown)}" "$stamp_file" > "$last_build"
echo
echo "== build summary =="
echo "binary:  $bin"
echo "git sha: ${TSFP_SOURCE_COMMIT:-$(git rev-parse --short HEAD 2>/dev/null || echo unknown)}"
echo "src stamp: $(cat "$stamp_file") ($stamp_file)"
echo "stamp:   $("$bin" --bevy-info 2>/dev/null | grep 'build stamp' || echo unknown)"
echo "options: $opts -DTSFP_LIFTED_DIR=${TSFP_LIFTED_DIR:-<auto>} (build dir $dir)"
echo "ui-rust: $ui_preview $ui_preview_state"
if [ "$with_tools" = 1 ]; then echo "storage: $storage_tool built"; else echo "storage: skipped (pass --with-tools for storage-import)"; fi
echo "next:    sh tools/dev/play.sh"

# T2118: opt-in PlayerSet weapon roots 1b7bc0/1c0200; retire own requires 52 roots.

# T1916: build_bevy.sh rebuilds stale cross-checkout runtime artifacts before linking the UI frame layers.

# T2316: relift includes observed original bot-handicap0x2C1040 and lives-HUD0x13DD40 callbacks for offline setup reference; native scoreboard remains live-gated.

# T2194: ports rebuild tracks the shared typed look_gate.rs contract; native 0xCFF20 targeting defaults on for selected player roots (TSFP_NATIVE_LOOK_GATE=0 A/B).

# T2328 candidate: TSFP_UI_NATIVE_EDITOR_CURSOR=1 opts into OS cursor/native hit-test on registered Map Maker pages; edit-view still uses the existing shim.
# T2329: TSFP_HUD_PRODUCER_SHADOW=1 observes typed weapon/message lifecycle against the original; diagnostic only, variants unchanged.
# T2329: native HUD owns weapon/row producers by default; TSFP_HUD_PRODUCERS=0 selects reference. Rebuild host and shell; pad-only UI diagnostics use TSFP_UI_PAD_REPLAY=1.

# T2194: live raw count arithmetic now uses the shared typed ViewAngles handler;
# zero-stick dispatch/profile overlays/guest camera commit remain TEMPORARY-SHIMs.

